from lib import *
S = SS('x20')
steps = [
    step("10 个 @Before 通知各带一个不同的切点,调用不同的方法,看命中了哪几个。orderService.place:execution(* OrderService.place(..))、execution(* OrderService.*(..))、target(Api)。cancel(带 @Audited):execution(* OrderService.*(..))、@annotation(Audited)、target(Api)。ping 只命中 execution(* OrderService.*(..)) 与 target(Api)。callInternal(内部又调 place)只命中 callInternal 自己,里面那次 place 没有命中任何通知(自调用,见后面的篇章)。payService.pay:within(PayService)、@within(Marked)、execution(public * *(..)) && within(PayService)。refund 多命中一个 execution(* *Service.re*(..))。userService.find(7L):execution(find(long)) && args(id) 拿到 id=7,bean(userService)。包可见的 pkgPrivate 和 protected 的 prot 在 CGLIB 代理下也命中了 execution(* OrderService.*(..))。", t=tl(S(1)), mark=lidx(S(1), 'callInternal', 'pkgPrivate', 'prot()'), done=lidx(S(1), 'orderService.place', 'orderService.cancel', 'payService.pay', 'payService.refund', 'userService.find'), b=bars([['place 命中的通知', 3, '3'], ['cancel 命中的通知', 3, '3'], ['pay 命中的通知', 3, '3'], ['refund 命中的通知', 4, '4'], ['callInternal 命中的通知', 2, '2(内部的 place 没命中)']], 4, done=[0, 1, 2, 3], mark=[4]), kv=KV([['execution', '按方法签名匹配'], ['within / @within', '按声明的类 / 类上的注解匹配'], ['@annotation / target / args / bean', '按方法注解、目标类型、参数、Bean 名匹配'], ['内部调用', '不经过代理,不命中']], ['内部调用'])),
    step("切点的类型决定每次调用要不要在运行时再判断。同一个 CostSvc.m(long) 通知里只做一个计数加一,每种切点各跑 3 次(5000000 次调用)。没有切面:约 1 到 2 ns,不是代理。execution(...):80、197、80 ns。execution(...) && args(id):192、210、189 ns。@annotation(Audited):215、250、149 ns。target(Api):221、228、182 ns。带 args 的、带 @annotation 的、带 target 的都比单纯的 execution 贵一倍左右(运行时还要判断参数、注解、目标类型)。最后一种 execution(...) && args(String):m 的参数是 long,静态就不可能匹配,没有创建代理,每次调用 0 到 1 ns,通知一次也没执行。同一个切点三次运行的耗时差别大(execution 一栏 80 到 197 ns),只能当量级参考。", t=tl(S(2)), mark=lidx(S(2), 'args(String)'), done=lidx(S(2), '没有切面', 'execution(...):每次', 'args(id)', '@annotation(Audited)', 'target(Api)'), b=bars([['没有切面 ns', 1, '1'], ['execution(...) ns', 80, '80(另两次 197、80)'], ['&& args(id) ns', 192, '192'], ['@annotation ns', 215, '215'], ['target(Api) ns', 221, '221'], ['args(String):静态不可能匹配 ns', 0, '0(不是代理)']], 250, done=[0, 5], cur=[1], mark=[2, 3, 4]), kv=KV([['只有 execution', '约 80 ns'], ['再加 args / @annotation / target', '约 150 到 250 ns'], ['静态不可能匹配', '不创建代理,没有开销'], ['噪声', '同一切点三次差别可到两倍']], ['静态不可能匹配'])),
]
A = mkartx('x20', 20, 'Spring,AOP,切点表达式,execution,within,真实验证,动画演示',
    '实测切点表达式匹配:execution、within、@within、@annotation、target、args、bean 各自命中哪些方法;自调用的内部方法不命中;CGLIB 代理下包可见和 protected 方法也被拦截;带 args、@annotation、target 的切点每次调用比单纯 execution 贵约一倍;静态就不可能匹配的切点不创建代理。',
    '切点表达式 execution、within、@annotation、target、args、bean 到底各自匹配什么?protected 和包可见的方法能不能被拦?不同写法每次调用的开销一样吗?这篇在 Spring Framework 7.0.9 上逐项验证。',
    [('10 个', '同时生效的 @Before 通知,各带一个不同写法的切点'), ('约 80 对 200 ns', '只有 execution 与再加 args / @annotation / target 的切点,每次调用的量级耗时'), ('0 个代理', 'args(String) 配 m(long) 这种静态就不可能匹配的切点,没有创建代理')],
    [('哪些写法命中什么', '<p>execution 按签名,within 与 @within 按类,@annotation 按方法注解,target、args、bean 按运行时对象、参数和 Bean 名。</p>'),
     ('运行时判断的代价', '<p>带 args、@annotation、target 的切点每次调用要多判断一次,比单纯 execution 贵一倍左右。</p>')],
    steps,
    [ENV_X + '。用不带 Boot 的 Spring Framework 7.0.9 + AspectJ 注解,proxyTargetClass = true;耗时是简单循环计时(没有用 JMH),三次运行的差别很大(例如 execution 一栏 80、197、80 ns),只能当量级参考;“包可见和 protected 方法命中”是在 CGLIB 代理、调用方与目标在同一个包的条件下测的',
     '没有验证:JDK 代理下 protected / 包可见方法;this 与 target 的区别;@args、@target 切点;reference pointcut(@Pointcut 复用);AspectJ 加载时织入;切点解析本身(parse)的耗时;多个切面同时匹配时的开销叠加'],
    '切点表达式')
